:root {
  --bg: #f6f5f1; --panel: #ffffff; --ink: #1c1d1f; --muted: #5d6066; --line: #d9d7d0;
  --accent: #1f5fa8; --warn-bg: #fff3d6; --warn-ink: #6b4a00; --bad-bg: #fde4e1; --bad-ink: #8a1f14;
  --chip: #ecebe6;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #16171a; --panel: #1f2125; --ink: #e9e9e6; --muted: #a2a5ab; --line: #34373d;
    --accent: #8ab8f0; --warn-bg: #3d3210; --warn-ink: #f2d98a; --bad-bg: #45201c; --bad-ink: #f5b3aa;
    --chip: #2b2e33;
  }
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink);
  font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif; }
main { max-width: 920px; margin: 0 auto; padding: 24px 16px 80px; }
h1 { font-size: 26px; margin: 0 0 4px; }
h2 { font-size: 19px; margin: 36px 0 10px; }
h3 { font-size: 16px; margin: 0 0 6px; overflow-wrap: anywhere; }
h4 { font-size: 12px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); margin: 16px 0 4px; }
p { margin: 0 0 8px; overflow-wrap: anywhere; }
a { color: var(--accent); }
.sub { color: var(--muted); margin-bottom: 4px; }
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 16px; margin: 0 0 14px; }
.across h3 { margin-top: 12px; }
.across h3:first-child { margin-top: 0; }
.meta { display: flex; flex-wrap: wrap; gap: 6px; margin: 6px 0; }
.chip { background: var(--chip); border-radius: 999px; padding: 1px 10px; font-size: 13px; }
.chip.own { font-weight: 600; }
.mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; }
.flag { background: var(--bad-bg); color: var(--bad-ink); border-radius: 6px; padding: 8px 10px; margin: 8px 0; overflow-wrap: anywhere; }
.gap { background: var(--warn-bg); color: var(--warn-ink); border-radius: 6px; padding: 6px 10px; }
ul { margin: 0 0 8px; padding-left: 20px; }
li { margin-bottom: 4px; overflow-wrap: anywhere; }
.scores { display: flex; flex-wrap: wrap; gap: 8px; }
.score { border: 1px solid var(--line); border-radius: 6px; padding: 4px 10px; min-width: 56px; text-align: center; }
.score b { display: block; font-size: 18px; }
.score span { font-size: 12px; color: var(--muted); }
.verdict { border-top: 1px solid var(--line); margin-top: 16px; padding-top: 12px; }
.verdict label { margin-right: 14px; white-space: nowrap; }
.verdict input[type=text] { width: 100%; margin-top: 8px; padding: 6px 8px; font: inherit;
  background: var(--bg); color: var(--ink); border: 1px solid var(--line); border-radius: 6px; }
button { font: inherit; padding: 6px 14px; border-radius: 6px; border: 1px solid var(--accent);
  background: var(--accent); color: var(--panel); cursor: pointer; }
textarea { width: 100%; min-height: 110px; margin-top: 10px; padding: 8px; background: var(--bg); color: var(--ink);
  border: 1px solid var(--line); border-radius: 6px; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 13px; }
details { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 10px 16px; margin-bottom: 10px; }
summary { cursor: pointer; font-weight: 600; }
details .item { border-top: 1px solid var(--line); padding: 10px 0; }
details .item:first-of-type { margin-top: 10px; }
.tray { position: sticky; bottom: 0; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 12px 16px; margin-top: 28px; }

(function () {
  "use strict";
  var data = JSON.parse(document.getElementById("round-data").textContent);
  var app = document.getElementById("app");
  var choices = {};

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) { node.className = cls; }
    if (text !== undefined && text !== null) { node.textContent = String(text); }
    return node;
  }
  function add(parent) {
    for (var i = 1; i < arguments.length; i++) { if (arguments[i]) { parent.appendChild(arguments[i]); } }
    return parent;
  }
  function safeLink(address, label) {
    var ok = false;
    try { ok = new URL(address).protocol === "https:"; } catch (e) { ok = false; }
    if (!ok) { return el("span", "mono", address); }
    var a = el("a", null, label || address);
    a.href = address; a.target = "_blank"; a.rel = "noopener noreferrer";
    return a;
  }
  function section(parent, heading, text) {
    add(parent, el("h4", null, heading), el("p", null, text));
  }
  function list(parent, heading, items) {
    if (!items || !items.length) { return; }
    var ul = el("ul");
    items.forEach(function (item) { ul.appendChild(el("li", null, item)); });
    add(parent, el("h4", null, heading), ul);
  }

  add(app, el("h1", null, "Review Round"),
    el("p", "sub", "Operator " + data.round.operator + " · " + data.round.date + " · " + data.round.window),
    el("p", "sub", "Searched: " + data.round.searched));

  add(app, el("h2", null, "Across this round"));
  var across = el("div", "panel across");
  data.across.forEach(function (item) { add(across, el("h3", null, item.heading), el("p", null, item.text)); });
  app.appendChild(across);

  var output = el("textarea");
  output.readOnly = true;
  output.setAttribute("aria-label", "Chosen Verdicts as text");

  function refresh() {
    var lines = [];
    data.repos.forEach(function (repo) {
      repo.cards.forEach(function (card) {
        var c = choices[card.id];
        if (c && c.verdict) {
          lines.push(card.id + " @ " + card.head + " | " + c.verdict + " | " + (c.notes || "").replace(/\s+/g, " ").trim());
        }
      });
    });
    output.value = lines.join("\n");
  }

  data.repos.forEach(function (repo) {
    add(app, el("h2", null, repo.name), el("p", "sub", repo.note));
    repo.cards.forEach(function (card) {
      var box = el("div", "panel");
      var title = el("h3");
      add(title, safeLink(card.url, repo.name + "#" + card.number), document.createTextNode(" " + card.title));
      box.appendChild(title);

      var meta = el("div", "meta");
      add(meta, el("span", "chip mono", card.head.slice(0, 7)), el("span", "chip own", card.ownership),
        el("span", "chip", card.bucket), el("span", "chip", card.size));
      if (card.base) { meta.appendChild(el("span", "chip", "base: " + card.base)); }
      add(box, meta, el("p", "sub", card.ownerDetail), el("p", "sub", card.status));

      card.flags.forEach(function (flag) { box.appendChild(el("div", "flag", flag)); });

      section(box, "What changed and why", card.what);
      list(box, "Claimed, not in the diff", card.claimed);
      list(box, "Left out of the description", card.leftOut);
      section(box, "Specification", card.spec);

      box.appendChild(el("h4", null, "Scores"));
      var scores = el("div", "scores");
      [["I", "Impact"], ["C", "Confidence"], ["V", "Verify"], ["U", "Undo"]].forEach(function (pair) {
        var s = el("div", "score");
        add(s, el("b", null, card.scores[pair[0]]), el("span", null, pair[1]));
        scores.appendChild(s);
      });
      var lev = el("div", "score");
      add(lev, el("b", null, card.scores.leverage), el("span", null, "Leverage"));
      scores.appendChild(lev);
      add(box, scores, el("p", "sub", card.scoreNote));
      section(box, "Hold test", card.hold);

      section(box, "Stored or published names", card.names);
      add(box, el("h4", null, "Evidence"), el("p", card.evidence.indexOf("None") === 0 ? "gap" : null, card.evidence));
      if (card.design) { section(box, "Design system", card.design); }
      section(box, "What was read and what was not", card.read);
      box.appendChild(el("p", "sub", card.walk));

      var verdict = el("div", "verdict");
      verdict.appendChild(el("h4", null, "Verdict"));
      choices[card.id] = { verdict: "", notes: "" };
      ["merge", "request changes", "defer"].forEach(function (value) {
        var label = el("label");
        var radio = el("input");
        radio.type = "radio"; radio.name = "verdict-" + card.id; radio.value = value;
        radio.addEventListener("change", function () { choices[card.id].verdict = value; refresh(); });
        add(label, radio, document.createTextNode(" " + value));
        verdict.appendChild(label);
      });
      var notes = el("input");
      notes.type = "text"; notes.placeholder = "Notes (optional, one line)";
      notes.setAttribute("aria-label", "Notes for " + card.id);
      notes.addEventListener("input", function () { choices[card.id].notes = notes.value; refresh(); });
      verdict.appendChild(notes);
      box.appendChild(verdict);
      app.appendChild(box);
    });
  });

  add(app, el("h2", null, "Collapsed sections"));

  function fold(titleText, items, emptyText, render) {
    var d = el("details");
    d.appendChild(el("summary", null, titleText + " (" + items.length + ")"));
    if (!items.length) { d.appendChild(el("p", "sub", emptyText)); }
    items.forEach(function (item) { d.appendChild(render(item)); });
    app.appendChild(d);
    return d;
  }
  fold("Dependency bots", data.bots, "No Dependabot or Renovate pull requests are open.", function () { return el("div"); });
  fold("In progress", data.inProgress, "No trusted-owner pull requests are still in progress.", function () { return el("div"); });
  var merged = fold("Recently auto-merged", data.merged, "Nothing merged without you in the window.", function (item) {
    var row = el("div", "item");
    var head = el("p");
    add(head, safeLink(item.url, item.id), document.createTextNode(" " + item.title));
    add(row, head, el("div", "meta"));
    add(row.lastChild, el("span", "chip", item.kind), el("span", "chip mono", item.vu));
    add(row, el("p", null, item.summary), el("div", "flag", item.finding));
    return row;
  });
  merged.open = true;
  merged.appendChild(el("p", "sub", data.mergedNote));

  var tray = el("div", "tray");
  var copy = el("button", null, "Copy Verdicts");
  copy.type = "button";
  var said = el("span", "sub", "");
  copy.addEventListener("click", function () {
    output.focus(); output.select();
    var done = function () { said.textContent = " Copied."; };
    var manual = function () { said.textContent = " Select the text below and copy it by hand."; };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(output.value).then(done, manual);
    } else { manual(); }
  });
  add(tray, copy, said, el("p", "sub", "One line per pull request: owner/repo#number @ reviewed head | verdict | notes"), output);
  app.appendChild(tray);
  refresh();
})();
